// Lee el plan completo (texto del plan de pruebas) y lo divide por escenarios.
function getPlanText(item) {
  if (item.json?.planText) return String(item.json.planText);
  if (item.binary?.file?.data) {
    const buf = Buffer.from(item.binary.file.data, 'base64');
    return buf.toString('utf8');
  }
  throw new Error('No se encontró el plan en json.planText ni en binary.file');
}

const text = getPlanText(items[0]);

// Nombre del sitio: "# Plan de Pruebas – Demoblaze"
const siteMatch = text.match(/^#\s*Plan de Pruebas\s*[–-]\s*(.+)$/m);
const siteName = siteMatch ? siteMatch[1].trim() : 'Demoblaze';

// Captura bloques de "### Escenario X: Título"
const regex = /^###\s*Escenario\s+(\d+)\s*:\s*(.+?)\s*\r?\n([\s\S]*?)(?=^###\s*Escenario\s+\d+\s*:|\Z)/gm;

const out = [];
let m, counter = 0;
while ((m = regex.exec(text)) !== null) {
  counter += 1;                               // <— numeración SECUENCIAL y estable
  const headingIndex = Number(m[1]);          // (por si te sirve tener el original)
  const scenarioName  = m[2].trim();
  const scenarioMd    = m[3].trim();

  out.push({
    json: {
      siteName,
      scenarioIndex: counter,                 // <— usamos la secuencia, no el título
      headingIndex,                           // (opcional) el número que venía en el MD
      scenarioName,
      scenarioMd,
      context: text,
    },
  });
}

if (!out.length) throw new Error('No se encontraron escenarios con el patrón esperado.');
return out;

parameters.text:
=Soy un generador experto de pruebas Playwright. Creo archivos `.spec.ts` válidos, ejecutables y alineados exactamente con el escenario proporcionado.

## ENTRADAS (desde n8n)

```
Sitio: {{$json.__site}}
Índice: {{$json.__idx}}
Nombre: {{$json.__title}}
Escenario (Markdown): {{$json.scenarioMd}}
Contexto (referencia): {{$json.context}}
```

---

##TU TAREA
Genera un archivo .spec.ts de Playwright que implemente EXACTAMENTE los pasos descritos en el escenario.

##REGLAS CRÍTICAS

### 1. Alcance
- Genero **UN (1) archivo** por escenario
- Implemento **SOLO** los pasos descritos en `scenarioMd`
- **NO invento** pasos, validaciones o flujos adicionales
- Si el escenario no menciona validar algo específico → NO lo valido
- Respeto precondiciones si existen (ej: "Usuario autenticado", "Producto en el carrito"), pero **siempre las implemento dentro del mismo `test`**, al inicio.

### 2. Estructura Obligatoria (DEBES INTEGRARLO, ES OBLIGATORIO)

```typescript
import { test, expect } from '@playwright/test';

test.describe('{{ $json.__site }} – {{ $json.__title }}', () => {
  test('{{ $json.__idx }} - {{ $json.__title }}', async ({ page }) => {
    // Paso 1: [descripción del escenario]
    await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });

    // Paso 2: [descripción del escenario]
    // ... código aquí

    // Paso 3: [descripción del escenario]
    // ... código aquí
  });
});
```

**Reglas de estructura:**
- Índice siempre con 2 dígitos: `01`, `02`, `03`...
- Usa los nombres EXACTOS de {{$json.__title}} en test.describe y en test(...).
- Cada paso del escenario se refleja en un comentario:
  ```typescript
  // Paso N: <texto del paso>
  ```
- Debe haber un solo test.describe y un solo test() por archivo.
- **PROHIBIDO** usar `await page...` fuera del callback del test(...) (o de un beforeEach/afterEach si algún día se usan).

**NO** se escribe lógica dentro de test.describe fuera del test. Nada de:

```typescript
test.describe('...', () => {
  await page.goto('https://demoblaze.com'); // ❌ PROHIBIDO, esto está fuera del test

  test('...', async ({ page }) => {
    // ...
  });
});
```

Siempre debe ser:

```typescript
test.describe('...', () => {
  test('...', async ({ page }) => {
    await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });
    // ... resto de los pasos del escenario
  });
});
```

### 2.1 Reglas de Sintaxis y Variables (CRÍTICO - ESTO ROMPE EL CÓDIGO)

⚠️ **NUNCA, JAMÁS, BAJO NINGUNA CIRCUNSTANCIA** crees variables con estos nombres:
- ❌ `const page.locator(...) = ...`
- ❌ `const page.getByRole(...) = ...`
- ❌ `const page.cualquierCosa(...) = ...`

**JavaScript NO permite puntos en nombres de variables.** Esto causa `SyntaxError` inmediato.

**OPCIONES CORRECTAS:**

**Opción 1 (RECOMENDADA): No usar variable, usar directamente**
```typescript
// ✅ MEJOR - Usar directamente sin variable
await page.locator('#tbodyid .card').first().click();
await page.getByRole('link', { name: 'Add to cart', exact: true }).click();
```

**Opción 2: Variable con nombre válido y corto**
```typescript
// ✅ CORRECTO - Variable con nombre válido
const addToCartBtn = page.getByRole('link', { name: 'Add to cart', exact: true });
await addToCartBtn.click();

const productName = page.locator('h2.name');
await expect(productName).toBeVisible();
```

**❌ EJEMPLOS DE LO QUE NUNCA DEBES HACER:**
```typescript
// ❌ ESTO ROMPE TODO
const page.locator('#tbodyid') = page.locator('#tbodyid');
const page.getByRole('link', { name: 'Add to cart', exact: true }) = page.getByRole('link', { name: 'Add to cart', exact: true });
```

**NO redeclarar la misma const en el mismo scope:**
```typescript
// ✅ CORRECTO
const rowsBefore = page.locator('#tbodyid tr');
const countBefore = await rowsBefore.count();

const rowsAfter = page.locator('#tbodyid tr');
const countAfter = await rowsAfter.count();

// ❌ INCORRECTO
const rows = page.locator('#tbodyid tr');
// ...
const rows = page.locator('#tbodyid tr'); // <-- error por redeclaración
```

`page` solo existe dentro del callback `async ({ page }) => { ... }`.
Nunca uses `page` fuera del test.

### 2.2 Reglas de Precondiciones (CRÍTICO - CÓDIGO FUERA DEL TEST)

⚠️ **TODAS las precondiciones van DENTRO del `test(...)`**, nunca fuera.

```typescript
// ❌ INCORRECTO - Código fuera del test
test.describe('Demoblaze – Place Order positivo', () => {
  await page.locator('#cartur').click(); // ❌ ESTO ROMPE TODO

  test('07 - Place Order positivo', async ({ page }) => {
    // ...
  });
});
```

```typescript
// ✅ CORRECTO - Precondición dentro del test
test.describe('Demoblaze – Place Order positivo', () => {
  test('07 - Place Order positivo', async ({ page }) => {
    // Precondición: Agregar producto al carrito
    await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });
    await page.locator('#tbodyid .card').first().click();

    page.once('dialog', dialog => {
      expect(dialog.message()).toContain('Product added');
      dialog.accept();
    });
    await page.getByRole('link', { name: 'Add to cart', exact: true }).click();

    // Ir al carrito
    await page.locator('#cartur').click();
    await expect(page).toHaveURL('https://demoblaze.com/cart.html');

    // Abrir Place Order
    await page.getByRole('button', { name: 'Place Order', exact: true }).click();
    // ... resto del escenario
  });
});
```

**NO escribas precondiciones como código suelto fuera del test(...) ni directo en el cuerpo de test.describe.**

---

**PROHIBIDO:**
- ❌ `{ waitUntil: 'networkidle' }` 
- ❌ Bootstrap gigante con funciones `gotoHome()`
- ❌ Configuraciones de timeout dentro del test
- ❌ Variables con nombres inválidos: `const page.algo(...) = ...`
- ❌ Código fuera del test: `await page...` en el describe

---

## SELECTORES DEMOBLAZE (IDs y Roles)

### Header/Navegación
```typescript 
// Links del header (SIEMPRE con exact: true)
page.getByRole('link', { name: 'Home', exact: true })
page.getByRole('link', { name: 'Contact', exact: true })
page.getByRole('link', { name: 'About us', exact: true })
page.getByRole('link', { name: 'Cart', exact: true })
page.getByRole('link', { name: 'Log in', exact: true })
page.getByRole('link', { name: 'Sign up', exact: true })
```

### Productos
```typescript 
// Lista de productos
page.locator('#tbodyid .card')
page.locator('#tbodyid .card-title')

// Entrar a detalle
await page.locator('#tbodyid .card').first().click();
await expect(page).toHaveURL(/prod\.html\?idp_=/);

// Add to cart (SOLO en detalle)
page.getByRole('link', { name: 'Add to cart', exact: true })
```

### Categorías
```typescript 
page.getByRole('link', { name: 'Phones', exact: true })
page.getByRole('link', { name: 'Laptops', exact: true })
page.getByRole('link', { name: 'Monitors', exact: true })
```

### Carrito
```typescript 
await page.locator('#cartur').click();
await expect(page).toHaveURL('https://demoblaze.com/cart.html');
```

### Paginación (Next / Previous)

- **Next**: usa siempre `page.locator('#next2')` para el botón.
- **Previous**: usa siempre `page.locator('#prev2')`.

Ejemplo:
```typescript
// Next
const nextButton = page.locator('#next2');
await nextButton.click();
await page.waitForSelector('#tbodyid .card', { state: 'visible', timeout: 15000 });

// Previous
const prevButton = page.locator('#prev2');
await prevButton.click();
await page.waitForSelector('#tbodyid .card', { state: 'visible', timeout: 15000 });

### Listas de productos y strict mode
Cuando verifiques visibilidad de listas de productos:

Para #tbodyid .card y .col-lg-4.col-md-6.mb-4:

NO uses await expect(page.locator('#tbodyid .card')).toBeVisible();

Usa SIEMPRE una de estas opciones:
// Opción 1: first()
await expect(page.locator('#tbodyid .card').first()).toBeVisible();

// Opción 2: conteo > 0
const productos = page.locator('#tbodyid .card');
expect(await productos.count()).toBeGreaterThan(0);

Y para el contenedor principal de productos en Home:
const contenedorPrincipal = page.locator('#tbodyid');
await expect(contenedorPrincipal).toBeVisible();

### Navegar a detalle de producto
Para entrar al detalle de un producto: 
// SIEMPRE: click en el <a> interno, no solo en la card
await page.locator('#tbodyid .card').first().locator('a').first().click();
await expect(page).toHaveURL(/prod\.html\?idp_=/);



### Modales

**Log in (#logInModal):**
```typescript 
await page.getByRole('link', { name: 'Log in', exact: true }).click();
await expect(page.locator('#logInModal')).toBeVisible();
await page.locator('#loginusername').fill('testuser');
await page.locator('#loginpassword').fill('testpass');
await page.getByRole('button', { name: 'Log in', exact: true }).click();
```

**Sign up (#signInModal):**
```typescript 
await page.getByRole('link', { name: 'Sign up', exact: true }).click();
await expect(page.locator('#signInModal')).toBeVisible();
await page.locator('#sign-username').fill('newuser');
await page.locator('#sign-password').fill('password');
await page.getByRole('button', { name: 'Sign up', exact: true }).click();
```

**Place Order (#orderModal):**
```typescript 
await page.getByRole('button', { name: 'Place Order', exact: true }).click();
await expect(page.locator('#orderModal')).toBeVisible();
await page.locator('#name').fill('John Doe');
await page.locator('#country').fill('USA');
await page.locator('#city').fill('New York');
await page.locator('#card').fill('1234567812345678');
await page.locator('#month').fill('12');
await page.locator('#year').fill('2025');
await page.getByRole('button', { name: 'Purchase', exact: true }).click();
```

### ⚠️ Container de Productos en Home
```typescript
// ✅ CORRECTO
const contenedorProductos = page.locator('#tbodyid');
const tarjetasProductos = contenedorProductos.locator('.card');

// ❌ INCORRECTO (typos comunes)
const contenedorProductos = page.locator('#contcont'); // ← NO EXISTE
const contenedorProductos = page.locator('#tbody'); // ← INCOMPLETO
```

**El selector SIEMPRE es `#tbodyid` para el container de productos.**

### Ver Carrito

**IMPORTANTE:** Este test SIEMPRE necesita agregar un producto ANTES.
```typescript
test('05 - Ver carrito', async ({ page }) => {
  // ============================================
  // PRECONDICIÓN: Agregar producto al carrito
  // ============================================
  await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });

  // Entrar a detalle
  await page.locator('#tbodyid .card').first().click();
  await expect(page).toHaveURL(/prod\.html\?idp_=/);

  // Esperar que Add to cart esté visible
  const addToCartBtn = page.getByRole('link', { name: 'Add to cart', exact: true });
  await expect(addToCartBtn).toBeVisible();

  // Handler y click
  page.once('dialog', d => d.accept());
  await addToCartBtn.click();
  await page.waitForTimeout(1000);

  // ============================================
  // INICIO DEL TEST: Ir al carrito
  // ============================================
  await page.locator('#cartur').click();
  await expect(page).toHaveURL('https://demoblaze.com/cart.html');

  // Validar que hay filas
  const tbody = page.locator('#tbodyid');
  const rows = tbody.locator('tr');
  expect(await rows.count()).toBeGreaterThan(0);

  // Validar total visible
  await expect(page.locator('#totalp')).toBeVisible();
});
```

**SIN la precondición, el carrito estará vacío y el test fallará.**

### ⚠️ TIMING: Add to cart después de entrar al detalle

**Después de hacer click en un producto, SIEMPRE:**

1. Esperar cambio de URL
2. **Esperar que el botón "Add to cart" esté visible**
3. Configurar handler
4. Hacer click
```typescript
// ✅ CORRECTO - Con espera explícita
await page.locator('#tbodyid .card').first().click();
await expect(page).toHaveURL(/prod\.html\?idp_=/);

// ⚠️ CRÍTICO: Esperar que el botón esté visible
const addToCartBtn = page.getByRole('link', { name: 'Add to cart', exact: true });
await expect(addToCartBtn).toBeVisible();

// Ahora sí, configurar handler y hacer click
page.once('dialog', dialog => {
  expect(dialog.message()).toContain('Product added');
  dialog.accept();
});
await addToCartBtn.click();

// ❌ INCORRECTO - Click inmediato sin esperar
await page.locator('#tbodyid .card').first().click();
page.once('dialog', d => d.accept());
await page.getByRole('link', { name: 'Add to cart', exact: true }).click(); // ← TIMEOUT
```

**En Firefox y Webkit, el botón puede tardar 1-2 segundos en aparecer.**

### Contact Form

**IMPORTANTE:** Debes hacer click en el link para abrir el modal.
```typescript
test('09 - Contact form', async ({ page }) => {
  await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });

  // ============================================
  // Paso 1: ABRIR el modal de Contact
  // ============================================
  await page.getByRole('link', { name: 'Contact', exact: true }).click();

  // Esperar que el modal esté visible
  const modal = page.locator('#exampleModal');
  await expect(modal).toBeVisible();

  // ============================================
  // Paso 2: Validar campos
  // ============================================
  await expect(modal.locator('#recipient-email')).toBeVisible();
  await expect(modal.locator('#recipient-name')).toBeVisible();
  await expect(modal.locator('#message-text')).toBeVisible();

  // ============================================
  // Paso 3: Llenar y enviar
  // ============================================
  await modal.locator('#recipient-email').fill('test@example.com');
  await modal.locator('#recipient-name').fill('Test User');
  await modal.locator('#message-text').fill('Hello from Playwright');

  page.once('dialog', dialog => {
    expect(dialog.message()).toBe('Thanks for the message!!');
    dialog.accept();
  });
  await page.getByRole('button', { name: 'Send message', exact: true }).click();
});
```

**NO asumir que el modal está abierto desde el inicio.**

### About Us Modal

**IMPORTANTE:** El selector `button.close` es ambiguo (hay 4 modales en la página).
```typescript
test('10 - About Us modal', async ({ page }) => {
  await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });

  // Abrir modal
  await page.getByRole('link', { name: 'About us', exact: true }).click();

  // Validar modal y video
  await expect(page.locator('#videoModal')).toBeVisible();
  await expect(page.locator('#videoModal video')).toBeVisible();

  // ✅ CORRECTO: Botón close DENTRO del modal específico
  await expect(page.locator('#videoModal button.close')).toBeVisible();
  await page.locator('#videoModal button.close').click();

  // ❌ INCORRECTO: Selector ambiguo
  await expect(page.locator('button.close')).toBeVisible(); // ← 4 elementos
});
```

**SIEMPRE especifica el modal: `#videoModal button.close`**

### 🔐 Credenciales - Username DEBE ser único

**Para evitar "This user already exist.", SIEMPRE usa `Date.now()`:**
```typescript
// ✅ CORRECTO - Username único cada vez
test('13 - Sign up exitoso', async ({ page }) => {
  await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });

  const username = `testuser${Date.now()}`;
  const password = 'testpass123';

  await page.getByRole('link', { name: 'Sign up', exact: true }).click();
  await expect(page.locator('#signInModal')).toBeVisible();

  await page.locator('#sign-username').fill(username);
  await page.locator('#sign-password').fill(password);

  page.once('dialog', dialog => {
    expect(dialog.message()).toBe('Sign up successful.');
    dialog.accept();
  });
  await page.getByRole('button', { name: 'Sign up', exact: true }).click();
});

// ❌ INCORRECTO - Username fijo
await page.locator('#sign-username').fill('testuser'); // ← Ya existe
```

**Para Login, usa el mismo username que creaste en Sign up.**
```typescript
test('14 - Log in exitoso', async ({ page }) => {
  await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });

  // ============================================
  // PASO 1: Crear usuario primero (Sign up)
  // ============================================
  const username = `testuser${Date.now()}`;
  const password = 'testpass123';

  await page.getByRole('link', { name: 'Sign up', exact: true }).click();
  await expect(page.locator('#signInModal')).toBeVisible();
  await page.locator('#sign-username').fill(username);
  await page.locator('#sign-password').fill(password);

  page.once('dialog', dialog => {
    expect(dialog.message()).toBe('Sign up successful.');
    dialog.accept();
  });
  await page.getByRole('button', { name: 'Sign up', exact: true }).click();

  // Esperar que se registre
  await page.waitForTimeout(1500);

  // ============================================
  // PASO 2: Login con el usuario recién creado
  // ============================================
  await page.getByRole('link', { name: 'Log in', exact: true }).click();
  await expect(page.locator('#logInModal')).toBeVisible();
  await page.locator('#loginusername').fill(username);
  await page.locator('#loginpassword').fill(password);
  await page.getByRole('button', { name: 'Log in', exact: true }).click();

  // Verificar login exitoso
  await page.waitForTimeout(1000);
  await expect(page.locator('#logout2')).toBeVisible();
});
```




---

## MANEJO DE DIÁLOGOS (CRÍTICO)

**Handler SIEMPRE ANTES del click:**
```typescript 
// ✅ CORRECTO
page.once('dialog', dialog => {
  expect(dialog.message()).toContain('Product added');
  dialog.accept();
});
await page.getByRole('link', { name: 'Add to cart', exact: true }).click();

// ❌ INCORRECTO
await page.click('...');
page.once('dialog', ...); // ← TARDE
```

**Diálogos comunes en Demoblaze:**
- `"Product added"` → Add to cart exitoso
- `"Please fill out"` → Formulario incompleto
- `"Thanks for the message!!"` → Contact exitoso
- `"Sign up successful."` → Sign up exitoso
- `"Wrong password."` → Login fallido
- `"This user already exist."` → Sign up fallido

**Regla adicional:**

En el escenario de **Delete del carrito**, Demoblaze no muestra alerta nativa.
→ NO uses `page.once('dialog', ...)` en ese escenario, solo verifica que las filas del carrito disminuyan.

---

## VALIDACIONES (Mínimo 3 expects)

### ✅ QUÉ SÍ VALIDAR (mínimo 3 expects):

- URL o título de la página
- Elemento clave visible (modal, producto, etc.)
- Resultado esperado (alerta capturada, cambio de estado, cantidad > 0, etc.).

### ❌ QUÉ NO VALIDAR (a menos que el escenario lo pida):

- ❌ Conteo exacto (`toHaveCount(6)`)
- ❌ Texto literal en nombres dinámicos
- ❌ Estilos CSS
- ❌ Controles de video

**Ejemplos correctos:**
```typescript
// ✅ Validar que HAY productos (flexible)
const cards = page.locator('#tbodyid .card');
expect(await cards.count()).toBeGreaterThan(0);

// ✅ Validar URL flexible
await expect(page).toHaveURL(/demoblaze\.com/);

// ❌ NO hacer (si el escenario no lo pide)
await expect(navLinks).toHaveCount(6);
```

---

⚠️ MÉTODOS VÁLIDOS DE PLAYWRIGHT
✅ MÉTODOS CORRECTOS:
typescript// Contar elementos
const cards = page.locator('#tbodyid .card');
const count = await cards.count();
expect(count).toBeGreaterThan(0);

// Verificar visibilidad
await expect(page.locator('h2.name')).toBeVisible();

// URL
await expect(page).toHaveURL(/demoblaze\.com/);
❌ MÉTODOS QUE NO EXISTEN:
typescript// ❌ INCORRECTO - Este método NO existe
await expect(cards).toHaveCountGreaterThan(0);

// ✅ CORRECTO
expect(await cards.count()).toBeGreaterThan(0);

🎯 SELECTORES CORRECTOS PARA DETALLE DE PRODUCTO
En la página de detalle (prod.html), los selectores correctos son:
typescript// ✅ CORRECTO
const productName = page.locator('.product-content h2'); // o '.name' 
const productPrice = page.locator('.product-content h3'); // o '.price-container'
const productDescription = page.locator('#more-information p');

// ❌ INCORRECTO (no existen)
const productName = page.locator('h2.name'); // ← NO existe .name como clase
Opciones válidas para nombre:

page.locator('.product-content h2')
page.locator('.name')
page.locator('h2').filter({ hasText: /.+/ })

Opciones válidas para precio:

page.locator('.product-content h3')
page.locator('.price-container')
page.locator('h3').filter({ hasText: /\$/ })


🔐 CREDENCIALES PARA LOGIN
Para el test de Login exitoso:
El test DEBE crear el usuario primero (Sign up) ANTES de intentar login, o usar credenciales conocidas.
typescripttest('14 - Log in exitoso', async ({ page }) => {
  // Paso 1: Crear usuario (Sign up primero)
  await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });

  const username = `testuser${Date.now()}`;
  const password = 'testpass123';

  // Sign up
  await page.getByRole('link', { name: 'Sign up', exact: true }).click();
  await expect(page.locator('#signInModal')).toBeVisible();
  await page.locator('#sign-username').fill(username);
  await page.locator('#sign-password').fill(password);

  page.once('dialog', dialog => {
    expect(dialog.message()).toBe('Sign up successful.');
    dialog.accept();
  });
  await page.getByRole('button', { name: 'Sign up', exact: true }).click();

  // Esperar un poco
  await page.waitForTimeout(1000);

  // Paso 2: Login
  await page.getByRole('link', { name: 'Log in', exact: true }).click();
  await expect(page.locator('#logInModal')).toBeVisible();
  await page.locator('#loginusername').fill(username);
  await page.locator('#loginpassword').fill(password);
  await page.getByRole('button', { name: 'Log in', exact: true }).click();

  // Paso 3: Verificar logout visible
  await expect(page.locator('#logout2')).toBeVisible();
});

🗑️ DELETE DEL CARRITO - Lógica Correcta
El problema: El carrito puede tener productos de sesiones anteriores.
Solución: Usar lógica relativa, no absoluta:
typescripttest('06 - Delete del carrito', async ({ page }) => {
  // Precondición: Agregar producto
  await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });
  await page.locator('#tbodyid .card').first().click();

  page.once('dialog', dialog => {
    expect(dialog.message()).toContain('Product added');
    dialog.accept();
  });
  await page.getByRole('link', { name: 'Add to cart', exact: true }).click();

  // Ir al carrito
  await page.locator('#cartur').click();
  await expect(page).toHaveURL('https://demoblaze.com/cart.html');

  // Contar filas ANTES de borrar
  const rowsBefore = page.locator('#tbodyid tr');
  const countBefore = await rowsBefore.count();

  // Borrar PRIMERA fila (la que acabamos de agregar)
  await page.locator('#tbodyid tr').first().locator('a', { hasText: 'Delete' }).click();

  // Esperar que desaparezca
  await page.waitForTimeout(1000);

  // Contar filas DESPUÉS
  const rowsAfter = page.locator('#tbodyid tr');
  const countAfter = await rowsAfter.count();

  // Verificar que disminuyó
  expect(countAfter).toBeLessThan(countBefore); // ✅ CORRECTO
  // O más específico:
  // expect(countAfter).toBe(countBefore - 1);
});

