function escapeRegExp(s){ return String(s ?? '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function coalesce(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null) {
      const sv = typeof v === 'string' ? v : (typeof v === 'object' ? JSON.stringify(v) : String(v));
