/**
 * HOTFIX: Reescribe cualquier goto(..., { waitUntil: 'networkidle' }) a 'domcontentloaded'
 * y agrega inmediatamente `await page.waitForLoadState('load');`.
 * También maneja goto('https://demoblaze.com') sin opciones.
 */
function fixExistingGotoNetworkIdle(code) {
  // A) Demoblaze absoluto + networkidle
  code = code.replace(
    /([ \t]*)await\s+page\.goto\(\s*['"]https?:\/\/demoblaze\.com\/?['"]\s*,\s*\{\s*waitUntil\s*:\s*['"]networkidle['"]\s*\}\s*\)\s*;?/gmi,
    (m, indent) =>
      `${indent}await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });\n${indent}await page.waitForLoadState('load');`
  );

  // B) Cualquier URL + networkidle (catch-all)
  code = code.replace(
    /([ \t]*)await\s+page\.goto\(\s*([^,;]+?)\s*,\s*\{\s*waitUntil\s*:\s*['"]networkidle['"]\s*\}\s*\)\s*;?/gmi,
    (m, indent, urlExpr) =>
      `${indent}await page.goto(${urlExpr}, { waitUntil: 'domcontentloaded' });\n${indent}await page.waitForLoadState('load');`
  );

  // C) Demoblaze absoluto sin opciones
  code = code.replace(
    /([ \t]*)await\s+page\.goto\(\s*['"]https?:\/\/demoblaze\.com\/?['"]\s*\)\s*;?/gmi,
    (m, indent) =>
      `${indent}await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });\n${indent}await page.waitForLoadState('load');`
  );

  // D) Última red de seguridad: objeto con networkidle en cualquier orden
  code = code.replace(
    /([ \t]*)await\s+page\.goto\(\s*([^,;]+?)\s*,\s*\{([^}]*)\}\s*\)\s*;?/gmi,
    (m, indent, urlExpr, obj) => {
      if (/waitUntil\s*:\s*['"]networkidle['"]/i.test(obj)) {
        const objSafe = obj.replace(/waitUntil\s*:\s*['"]networkidle['"]/i, `waitUntil: 'domcontentloaded'`);
        return `${indent}await page.goto(${urlExpr}, { ${objSafe} });\n${indent}await page.waitForLoadState('load');`;
      }
      return m;
    }
  );

  return { code };
}

